'use strict';

/* ============================================================
   FitFlow — логика приложения
   Принципы:
   - Offline-first: всё хранится локально (localStorage),
     регистрация не требуется.
   - ИИ (Gemini / DeepSeek / YandexGPT) подключается позже и
     только как дополнение к локальному парсеру.
   ============================================================ */

/* ---------- Утилиты ---------- */
const $ = (sel) => document.querySelector(sel);
/* ВАЖНО: $$ всегда возвращает Array, а не NodeList — иначе .some/.map/.filter
   падают с «is not a function» (NodeList знает только .forEach). */
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

const fmt = (n) => Math.round(n).toLocaleString('ru-RU');

function todayKey() {
  const d = new Date();
  const p = (x) => String(x).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

